mapper.update:
merge into T_NC_GLUE_GROUP_ORDER a USING (
select #{GlueGroupOrder.glueGroupCode,jdbcType=VARCHAR} GLUE_GROUP_CODE, #{GlueGroupOrder.glueGroupName,jdbcType=VARCHAR} GLUE_GROUP_NAME, #{GlueGroupOrder.orderNum,jdbcType=DOUBLE} ORDER_NUM, #{GlueGroupOrder.createBy,jdbcType=VARCHAR} create_by, #{GlueGroupOrder.createTime,jdbcType=DATE} create_time, #{GlueGroupOrder.updateBy,jdbcType=VARCHAR} update_by, #{GlueGroupOrder.updateTime,jdbcType=DATE} update_time, #{GlueGroupOrder.remark,jdbcType=VARCHAR} remark from dual
) b ON ( a.GLUE_GROUP_CODE = b.GLUE_GROUP_CODE AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.GLUE_GROUP_NAME = b.GLUE_GROUP_NAME, a.ORDER_NUM = b.ORDER_NUM, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT ( a.id , a.GLUE_GROUP_CODE , a.GLUE_GROUP_NAME , a.ORDER_NUM , a.create_by , a.create_time , a.remark, a.del_flag ) values (SEQ_PUBLIC.NEXTVAL, b.GLUE_GROUP_CODE, b.GLUE_GROUP_NAME, b.ORDER_NUM, b.create_by, sysdate, b.remark, '0' )
